INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('00093272-c254-4043-a3d3-cde990d26204', 'STEP 1', '1. For all parameters under the Cable Modem module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Initiate a SET operation on all those parameters with the same value retrieved using the previous GET operation but with an incorrect datatype using WebPA protocol.
3. The parameter will be write type compliant if the SET operations fail with the expected error code.
4. Return success if all applicable parameters are write type compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in Cable Modem module should throw the expected error code when a SET operation is attempted on it with an invalid parameter type using WebPA protocol.', 'e3d7ec1f-7a54-4390-b586-1e0b8d850a8d', '2026-03-19 06:39:37.951895', '2026-03-19 06:39:37.951897');
