INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7f3fc1d5-ea4d-47a2-be2c-cf53b4f9041a', 'STEP 3', 'Configure ACS to send GET task request for getting the object Device.Time.', 'Should successfully return 200 as status code and a non-empty query response.', 'ac8f791a-20ba-4232-bab5-2ef215d00e2d', '2026-04-01 19:36:47.275053', '2026-04-01 19:36:47.275054');
