INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c50f3e40-eac5-4629-9e57-8ae7a6fe4a7d', 'STEP 2', 'Get radio interface prefix from platform properties', 'Should retrieve RADIO_IF_PREFIX from platform properties', 'd5c1a62b-d496-441d-a7ed-ed312b80e136', '2026-04-01 06:55:16.597522', '2026-04-01 06:55:16.597523');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8972fe31-8995-44b5-9743-49e4f626a891', 'STEP 3', 'Get link addr from MLD Interface info for this link ID', 'Should retrieve link addr for MLD link ID', 'd5c1a62b-d496-441d-a7ed-ed312b80e136', '2026-04-01 06:55:16.598374', '2026-04-01 06:55:16.598375');
