INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('010e2c33-ab3d-4803-9e12-49811376735f', 'STEP 1', '1. Identify all table objects of type "dynamicTable" under the LMLite module which are applicable for the device platform under test.
2. Proceed to an add table row operation for all those identified table objects using WebPA protocol.
3. Check if the add table row operation fails with the expected error code for Dynamic Tables.
4. Return success if rows do not get added to the applicable Dynamic Tables. Else, return failure and publish the failed tables.', 'Adding rows to dynamic table objects under LMLITE module using WebPA protocol should return the expected error code.', '35506e9d-8b3e-4a8f-bd6f-d217bcb21144', '2026-03-19 06:39:41.625828', '2026-03-19 06:39:41.625829');
DELETE FROM test_step WHERE script_id = 'de690fc8-6ca6-4dc5-8573-48b2eb4d8654';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0119ba65-fd7a-4f04-a228-689617aaf93c', 'STEP 1', '1. Identify all table objects of type "dynamicTable" under the PAM module which are applicable for the device platform under test.
2. For all applicable Dynamic Tables, get the current number of rows.
3. For Dynamic Tables with row count greater than 0, perform a delete table row operation of the last table row instance using WebPA protocol.
4. Check if the delete table row operation fails with the expected error code for Dynamic Tables.
5. Return success if rows do not get deleted from the applicable Dynamic Tables. Else, return failure and publish the failed tables.', 'Deleting rows from dynamic table objects under PAM module using WebPA protocol should return the expected errorcode.', 'de690fc8-6ca6-4dc5-8573-48b2eb4d8654', '2026-03-19 06:39:37.914396', '2026-03-19 06:39:37.914398');
DELETE FROM test_step WHERE script_id = 'c2bd75fa-7333-4bec-9d5f-2946b16cb1b0';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f5622c7d-ce2c-49a7-bb08-b33ad2fa4586', 'Create Display', 'Create WAYLAND_DISPLAY via RDKWindowManager.createDisplay and verify via RDKWindowManager.getApps', 'WAYLAND_DISPLAY named test must be created', 'c2bd75fa-7333-4bec-9d5f-2946b16cb1b0', '2026-03-30 07:39:09.965585', '2026-03-30 07:39:09.965587');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4aa77454-ea2b-4ed3-93ff-a401590e3d5e', 'Set environment', 'Set WAYLAND_DISPLAY to test and XDG_RUNTIME_DIR', 'WAYLAND_DISPLAY and XDG_RUNTIME_DIR must be successfully set', 'c2bd75fa-7333-4bec-9d5f-2946b16cb1b0', '2026-03-30 07:39:09.967891', '2026-03-30 07:39:09.967892');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('029d4b57-61b6-4a42-b714-ae02ed65f24c', 'Vulkan Graphics Pipeline Initialization', ' Initialize Vulkan instance with Wayland surface extensions, create Wayland surface, enumerate and select physical device with graphics capabilities, create logical device with graphics queue, setup swapchain with user-specified resolution, create render pass for color attachment, and allocate framebuffers for each swapchain image.', 'Vulkan instance created successfully, Wayland surface established, physical device selected with graphics queue family, logical device and swapchain initialized without errors, render pass and framebuffers created for specified resolution.

', 'c2bd75fa-7333-4bec-9d5f-2946b16cb1b0', '2026-03-30 07:39:09.969195', '2026-03-30 07:39:09.969196');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8977700d-ec16-46cb-957b-bb0ae171a68f', 'Ball Physics and Animation System Setup', 'Initialize ball physics arrays for position, velocity, and state tracking, setup animation parameters for bouncing ball mechanics with collision detection, configure ball count mode (constant 1 ball or increasing stress test), initialize random seed for ball positioning and movement patterns.', 'Ball physics system initialized with proper array allocations, animation parameters configured for realistic bouncing behavior, ball count mode set according to test configuration, random movement patterns established for dynamic animation.', 'c2bd75fa-7333-4bec-9d5f-2946b16cb1b0', '2026-03-30 07:39:09.970250', '2026-03-30 07:39:09.970251');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('57999ed8-674e-4bcb-ad42-708ee4d2854a', 'Multi-Layer Render Pass Recording', 'Record command buffers for each frame with background rendering (white clear color), animated ball drawing with variable sizes and colors, overlay notification rendering during 4-second cycles, implement dynamic render target switching between background and overlay content, optimize command buffer recording for layered content.', 'Command buffers recorded successfully with proper render pass structure, background and ball animation commands properly sequenced, overlay notification rendering integrated with timing control, multi-layer composition achieved without rendering artifacts.', 'c2bd75fa-7333-4bec-9d5f-2946b16cb1b0', '2026-03-30 07:39:09.971165', '2026-03-30 07:39:09.971166');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7072b39d-eb05-4e97-83f3-466f7b08d602', 'Overlay Notification System Validation', 'xecute notification popup system with precise 4-second timing cycles (active during seconds 3-4, 7-8, etc.), render animated orange notification box with pulsing effects, implement segmented overlay rendering based on ball count, validate overlay appears and disappears correctly over animated background content.', 'Notification popups appear at exact 4-second intervals, orange overlay box renders with proper animation effects, segmented rendering matches ball count accurately, overlay visibility toggles correctly without affecting background animation timing.', 'c2bd75fa-7333-4bec-9d5f-2946b16cb1b0', '2026-03-30 07:39:09.971528', '2026-03-30 07:39:09.971530');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('52141778-c581-44da-aa61-399b8301a0b3', 'Performance Monitoring and CSV Export', 'Monitor real-time FPS and CPU usage every second during test execution, track performance impact when overlay notifications are active versus inactive, calculate average statistics over test duration, export per-second performance data to CSV file with API, resolution, ball count, FPS, and CPU usage columns.', 'Performance monitoring captures accurate FPS and CPU metrics, overlay impact measured correctly (2-4% CPU increase during notification cycles), average statistics calculated properly, CSV export generates valid file with properly formatted performance data for analysis.', 'c2bd75fa-7333-4bec-9d5f-2946b16cb1b0', '2026-03-30 07:39:09.972461', '2026-03-30 07:39:09.972462');
DELETE FROM test_step WHERE script_id = 'e723bce1-ea90-43fb-ba48-150f3e0919e9';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('037ade5d-16b9-46fb-b340-f0f628d80b54', 'STEP 1', '1. For writable parameters, check if L2 SET use-case is defined.
2. For those parameters with L2 SET use-case defined, get the initial value. Return failure if get operation fails.
3. Then determine the value to be SET from the permissible value ranges of SET values.
4. For the SET value determined, get the initial values of defined dependencies if any. Return failure if any of the get operations fail.
5. Execute the SET operation of the parameters after all dependencies are SET successfully. If any of the SET operations fail, return failure.
6. Confirm with GET operation if all values are SET properly. Return failure if any SET value did not reflect in GET.
7. Now, revert the parameter to the initial value after identifying all revert dependencies and setting them. Return failure if any SET operations fail during revert or if SET does not reflect in GET.', 'All L2 SET operations should be successful and the corresponding use-cases under ADVSEC module should be validated successfully.', 'e723bce1-ea90-43fb-ba48-150f3e0919e9', '2026-03-19 06:39:40.468188', '2026-03-19 06:39:40.468189');
DELETE FROM test_step WHERE script_id = '76e901cc-aace-4f00-b8a8-222a0382a18f';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8e11257e-708c-4596-bd97-691ccb4ae4c8', 'Create Display', 'Create WAYLAND_DISPLAY via RDKWindowManager.createDisplay and verify via RDKWindowManager.getApps', 'WAYLAND_DISPLAY named test must be created', '76e901cc-aace-4f00-b8a8-222a0382a18f', '2026-03-30 06:49:53.589374', '2026-03-30 06:49:53.589376');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0f07944b-9ead-478d-a2b8-b5295c90929b', 'Set environment', 'Set WAYLAND_DISPLAY to test and XDG_RUNTIME_DIR', 'WAYLAND_DISPLAY and XDG_RUNTIME_DIR must be successfully set', '76e901cc-aace-4f00-b8a8-222a0382a18f', '2026-03-30 06:49:53.590285', '2026-03-30 06:49:53.590286');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d994ccd6-aed9-4972-aa3a-0491fdcb2e91', 'Vulkan Multi-Threading Pipeline Initialization', 'Initialize Vulkan instance with Wayland surface, create logical device and swapchain, setup render pass and framebuffers, create separate command pools for each thread (--threads parameter), load and compile shaders for rectangle rendering.', 'Vulkan graphics pipeline must be created successfully, per-thread command pools allocated, shader modules loaded without errors, graphics pipeline ready for parallel command buffer recording.', '76e901cc-aace-4f00-b8a8-222a0382a18f', '2026-03-30 06:49:53.591053', '2026-03-30 06:49:53.591054');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1ae14e31-b9cb-43cb-8b3a-6df1fa22c671', 'Secondary Command Buffer Allocation and Thread Setup', 'Allocate primary and secondary command buffers, create secondary command buffers for each thread (THREADS count), setup inheritance info for secondary buffers to work within render pass, prepare thread-safe command recording infrastructure.', 'All secondary command buffers must be allocated successfully, per-thread command pools created, inheritance information properly configured for render pass compatibility.', '76e901cc-aace-4f00-b8a8-222a0382a18f', '2026-03-30 06:49:53.591860', '2026-03-30 06:49:53.591861');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('39c0a110-c62d-4a90-aa9e-909f41e4edf0', 'Rectangle Generation and Multi-Threaded Recording', 'Generate specified number of rectangles (--rects parameter) with random positions and colors, spawn worker threads to record secondary command buffers in parallel, each thread records subset of rectangles with animated positions and push constants.', 'Rectangle objects created with randomized properties, worker threads must record command buffers simultaneously without conflicts, each thread processes assigned rectangle subset efficiently.', '76e901cc-aace-4f00-b8a8-222a0382a18f', '2026-03-30 06:49:53.592800', '2026-03-30 06:49:53.592800');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('037fc325-e1d9-4411-8f87-82d4ecc2b987', 'Command Buffer Execution and Performance Monitoring', 'Execute secondary command buffers from primary command buffer using vkCmdExecuteCommands, submit to graphics queue with proper synchronization, monitor FPS and CPU usage every second, export performance data to CSV file.', 'All secondary command buffers executed correctly in single render pass, synchronization objects prevent race conditions, accurate FPS and CPU metrics calculated and exported to CSV.', '76e901cc-aace-4f00-b8a8-222a0382a18f', '2026-03-30 06:49:53.593705', '2026-03-30 06:49:53.593706');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('834f17a3-e4e6-4f86-8664-a78dde096735', 'Multi-Threading Validation and Resource Cleanup', 'Run test for specified duration (--time parameter), validate multi-threaded command recording performance compared to single-threaded approach, display final statistics showing threading efficiency, destroy all Vulkan resources and thread pools.', 'Test must complete after specified time duration, threading performance benefits demonstrated, final performance summary displayed, all per-thread command pools and Vulkan objects properly destroyed.', '76e901cc-aace-4f00-b8a8-222a0382a18f', '2026-03-30 06:49:53.596628', '2026-03-30 06:49:53.596629');
