INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('069efaa5-9dc6-41a3-963f-281db347efde', 'STEP 1', '1. For all parameters under the LMLITE module which are applicable for the device platform under test, perform a GET operation.
2. Check if the datatype of the value retrieved from the GET operation is type-compliant with respect to the RDKB specification.
3. If the parameter value complies with the expected type, proceed to verify whether it belongs to the list of expected values defined in the RDKB specification or, if not provided by RDKB, aligns with the Broadband Forum standard.
4. Return success if all parameter values are type compliant and falls in the expected value list. Else, return failure and publish the failed parameters list.', 'All DML parameter values retrieved under LMLITE module should be type compliant and the value must be from expected values list.', '6f3f57c2-309b-41cd-9c74-62bdc6cf2c3f', '2026-03-19 06:39:38.878430', '2026-03-19 06:39:38.878431');
