INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('06c2a30e-0ab8-412a-92e0-022807d5c90a', 'STEP 1', '1. Identify all table objects of type "staticTable" under the MTA Agent module which are applicable for the device platform under test.
2. Proceed to an add table row operation for all those identified table objects using WebPA protocol.
3. Check if the add table row operation fails with the expected error code for Static Tables.
4. Return success if rows do not get added to the applicable Static Tables. Else, return failure and publish the failed tables.', 'Adding rows to static table objects under MTA module using WebPA protocol should return the expected error code.', '2afe0f97-f3a8-4df8-9dc8-d92da18be98a', '2026-03-19 06:39:41.347379', '2026-03-19 06:39:41.347380');
