INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('08f85522-3fba-4e52-95ad-ef3f61e72b1d', 'STEP 1', '1. For all parameters under the Inter Device Manager module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Initiate a SET operation using WebPA protocol on all those parameters with the same value retrieved using the previous GET operation and with the parameter''s datatype.
3. The parameter will be write-access compliant if the SET operation does not fail with read-only error code.
4. Return success if all applicable parameters are write-access compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in Inter Device Manager module should not throw read-only error code when a SET operation is attempted on it using WebPA protocol.', '384cf89c-58a0-4b94-b35b-07e64037083a', '2026-03-19 06:39:41.837318', '2026-03-19 06:39:41.837319');
DELETE FROM test_step WHERE script_id = '5bd86382-6c42-480b-ab6b-deee5ded7483';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('095a4f78-03f5-4431-bd07-c148d612a33b', 'STEP 1', '1. For all parameters under the TELEMETRY module which are applicable for the device platform under test, perform a GET operation.
2. Check if the datatype of the value retrieved from the GET operation is type-compliant with respect to the RDKB specification.
3. If the parameter value complies with the expected type, proceed to verify whether it belongs to the list of expected values defined in the RDKB specification or, if not provided by RDKB, aligns with the Broadband Forum standard.
4. Return success if all parameter values are type compliant and falls in the expected value list. Else, return failure and publish the failed parameters list.', 'All DML parameter values retrieved under TELEMETRY module should be type compliant and the value must be from expected values list.', '5bd86382-6c42-480b-ab6b-deee5ded7483', '2026-03-19 06:39:41.075417', '2026-03-19 06:39:41.075419');
