INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b36291b5-2ff7-4397-b85e-818982f60335', 'TEST STEP 2', 'Ensure Remote Debugger Enable RFC is true, clear the RRD log file and delete the existing debug reports as a pre-requisite', 'The RFC must be true and the files must be cleared successfully.', '5c7a45af-2b0b-4cc2-9c80-0a8b4c0f6651', '2026-04-01 07:40:45.250453', '2026-04-01 07:40:45.250454');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('afc6bbe9-86b4-454d-b1be-26837302620f', 'TEST STEP 3', 'Get the initial value of Device.DeviceInfo.X_RDKCENTRAL-COM_RFC.Feature.RDKRemoteDebugger.IssueType and Device.DeviceInfo.X_RDKCENTRAL-COM_RFC.Feature.CDLDM.CDLModuleUrl', 'The initial value of RDKRemoteDebugger Enable is obtained successfully.', '5c7a45af-2b0b-4cc2-9c80-0a8b4c0f6651', '2026-04-01 07:40:45.251820', '2026-04-01 07:40:45.251821');
