INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5c2f5e4f-83ec-4e1f-8dc9-a1dc0c249674', 'TEST STEP 6', 'Check whether dynamic JSON file is fetched to the below path /tmp/RDK-RRD-Device/etc/rrd/remote_debugger.json.', 'The JSON file should be fetched and available in the designated location.', '5c7a45af-2b0b-4cc2-9c80-0a8b4c0f6651', '2026-04-01 07:40:45.254093', '2026-04-01 07:40:45.254094');
