INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('796124a8-33d1-4074-862b-7ff44e8e238c', 'TEST STEP 10', 'Unload the tdkbtr181 and sysutil modules.', 'The modules are unloaded successfully.', '5c7a45af-2b0b-4cc2-9c80-0a8b4c0f6651', '2026-04-01 07:40:45.256423', '2026-04-01 07:40:45.256424');
