INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0a4d8a44-f455-4c38-8a9d-ffd726cee75d', 'STEP 1', '1. Identify all table objects of type "staticTable" under the Test and Diagnostics module which are applicable for the device platform under test.
2. For all applicable Static Tables, get the current number of rows.
3. For Static Tables with row count greater than 0, perform a delete table row operation of the last table row instance using WebPA protocol.
4. Check if the delete table row operation fails with the expected error code for Static Tables.
5. Return success if rows do not get deleted from the applicable Static Tables. Else, return failure and publish the failed tables.', 'Deleting rows from static table objects under TDM module using WebPA protocol should return the expected errorcode.', '022e21de-84eb-4041-93a1-98b87dae1584', '2026-03-19 06:39:37.104784', '2026-03-19 06:39:37.104785');
