INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0a7a5be0-533c-49c4-8689-c893f459bcbe', 'STEP 1', '1. Identify all table objects of type "staticTable" under the WIFI module which are applicable for the device platform under test.
2. Proceed to an add table row operation for all those identified table objects.
3. Check if the add table row operation fails with the expected error code for Static Tables.
4. Return success if rows do not get added to the applicable Static Tables. Else, return failure and publish the failed tables.', 'Adding rows to static table objects under WIFI module should return the expected error code.', '1cdd235b-86c4-4185-9bc3-501e0b4b8674', '2026-03-19 06:39:38.118934', '2026-03-19 06:39:38.118935');
DELETE FROM test_step WHERE script_id = '4baf1a0e-c516-47c0-b438-49122d127e65';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0aa5d515-6de9-4c05-88d6-f22e87a63ce8', 'STEP 1', '1. For writable parameters, check if L2 SET use-case is defined.
2. For those parameters with L2 SET use-case defined, get the initial value. Return failure if get operation fails.
3. Then determine the value to be SET from the permissible value ranges of SET values.
4. For the SET value determined, get the initial values of defined dependencies if any. Return failure if any of the get operations fail.
5. Execute the SET operation of the parameters after all dependencies are SET successfully. If any of the SET operations fail, return failure.
6. Confirm with GET operation if all values are SET properly. Return failure if any SET value did not reflect in GET.
7. Now, revert the parameter to the initial value after identifying all revert dependencies and setting them. Return failure if any SET operations fail during revert or if SET does not reflect in GET.', 'All L2 SET operations should be successful and the corresponding use-cases under MOCA module should be validated successfully.', '4baf1a0e-c516-47c0-b438-49122d127e65', '2026-03-19 06:39:42.164957', '2026-03-19 06:39:42.164958');
DELETE FROM test_step WHERE script_id = 'db4c1282-a8b1-48ff-b73b-513629088e97';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0ae1d4fa-7473-4674-95c8-fbb85a3724ed', 'STEP 1', '1. Under the CR module, identify all the parameters with the read-only access type which are applicable for the device platform under test.
2. For all such parameters, perform a SET operation with a new value in line with the parameters''s datatype.
3. Check if the SET operation returns a FAILURE with the expected error code.
4. Return success if all read-only parameters fail with the expected return code. Else, return failure and publish the failed parameters list.', 'Setting the "read-only" TR-181 DML parameters under the CR module should return error code.', 'db4c1282-a8b1-48ff-b73b-513629088e97', '2026-03-19 06:39:40.554637', '2026-03-19 06:39:40.554638');
