INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0ebb3151-925f-4583-97ab-a8f4256fa01d', 'STEP 1', '1. For all parameters under the EthAgent module which are applicable for the device platform under test, perform a GET operation.
2. Initiate a SET operation on all those parameters with the same value retrieved using the previous GET operation but with an incorrect datatype.
3. The parameter will be write-type compliant if the SET operations fail with the expected error code.
4. Return success if all applicable parameters are write-type compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in EthAgent module should throw the expected error code when a SET operation is attempted on it with an invalid parameter type.', 'b55462d9-9175-4445-bbfd-970673674d38', '2026-03-19 06:39:36.314465', '2026-03-19 06:39:36.314467');
