INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0f81cb81-d08c-4fc0-89f6-60c256b63c0d', 'STEP 1', '1. Under the Vlan Manager module, identify all the parameters with the read-only access type which are applicable for the device platform under test.
2. For all such parameters, perform a SET operation with a new value in line with the parameters''s datatype using WebPA protocol.
3. Check if the SET operation returns a FAILURE with the expected error code.
4. Return success if all read-only parameters fail with the expected return code. Else, return failure and publish the failed parameters list.', 'Setting the "read-only" TR-181 DML parameters under the Vlan Manager module using WebPA protocol should return error code.', 'ac546d4d-c13d-4e35-99df-80b384fdd98b', '2026-03-19 06:39:40.993787', '2026-03-19 06:39:40.993789');
