INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('126900c6-4f98-4e57-a264-35e9fd0ebffa', 'Test Step 1', 'set_prerequisites function will set the export commands and start the westeros in the environment using the below commands
XDG_RUNTIME_DIR=/run 
WAYLAND_DISPLAY=main0 
WESTEROS_GL_GRAPHICS_MAX_SIZE=1280x1024 LD_PRELOAD=/usr/lib/libwesteros_gl.so.0.0.0 
westeros --renderer /usr/lib/libwesteros_render_gl.so.0 --display=main0 --window-size 1280x1024 &
or if RDKWindowManager is present, display is created via createDisplay API', 'Export values should be set successfully and Westeros needs to be started
