INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('253efba3-4b99-42d6-bc55-26ea7b45a4df', 'Test Step 2', 'Set Wayland Display and Runtime Directory using below command
