WAYLAND_DISPLAY=`basename $(ls -l /run/westeros* | grep -v ".lock" | awk ''{print $9}'')`', 'Wayland Display should set successfully', 'e37ca04a-a9ad-4267-89a4-e49fc9bf9a52', '2026-03-27 10:49:04.938142', '2026-03-27 10:49:04.938144');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9b558e49-7ac8-44d0-a894-916b60671d5c', 'Test Step 3', 'Execute vkmark test binary in DUT using vkmark command 
