INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d73e2695-597c-43bb-9443-b871fb97cbef', 'Test Step 4', 'Obtain the vkmark score with the frames rendered', 'vkmark score must be obtained', 'e37ca04a-a9ad-4267-89a4-e49fc9bf9a52', '2026-03-27 10:49:04.940799', '2026-03-27 10:49:04.940801');
