INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('13318253-4765-4faf-bdc9-e21fb1de5b41', 'STEP 1', '1. For all parameters under the ADVSEC module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Check if the datatype of the value retrieved from the GET operation is type-compliant with respect to the RDKB specification.
3. If the parameter value complies with the expected type, proceed to verify whether it belongs to the list of expected values defined in the RDKB specification or, if not provided by RDKB, aligns with the Broadband Forum standard.
4. Return success if all parameter values are type compliant and falls in the expected value list. Else, return failure and publish the failed parameters list.
', 'All DML parameter values retrieved under ADVSEC module using WebPA protocol should be type compliant and the value must be from expected values list.', 'f406ae59-e3bc-4d44-bcb9-742cfef5085e', '2026-03-19 06:39:40.422254', '2026-03-19 06:39:40.422255');
DELETE FROM test_step WHERE script_id = 'fd5f3226-3807-428b-8321-803653c0e3f6';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('142297ff-338a-4a11-9d7f-1bfcaf86aba7', 'STEP 1', '1. Identify all table objects of type "dynamicTable" under the LMLite module which are applicable for the device platform under test.
2. For all applicable Dynamic Tables, get the current number of rows.
3. For Dynamic Tables with row count greater than 0, perform a delete table row operation of the last table row instance using WebPA protocol.
4. Check if the delete table row operation fails with the expected error code for Dynamic Tables.
5. Return success if rows do not get deleted from the applicable Dynamic Tables. Else, return failure and publish the failed tables.', 'Deleting rows from dynamic table objects under LMLITE module using WebPA protocol should return the expected errorcode.', 'fd5f3226-3807-428b-8321-803653c0e3f6', '2026-03-19 06:39:37.540737', '2026-03-19 06:39:37.540738');
DELETE FROM test_step WHERE script_id = '0b737e88-3a81-4f88-8534-f460bb1de60d';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('147709c9-bc4f-41f7-9bf5-6e08cac6e92d', 'STEP 1', '1. Load the modules
2. From tdkbDmlModuleList fetch the different components under the ETHAGENT module
3. With the run-time config of each of the component perform the pre-requisite to collect the number of existing table rows under each table.
4. For each of the parent and child tables of object type "dynamicTable", perform delete table row operation for the last instance if the total number of table rows greater than 0.
5. DeleteRow operation on dynamic tables should return failure with errorcode the expected error code. Else, add the table to the failed params list.
6. Unload the modules.', 'Deleting rows from dynamic table objects under ETHAGENT module should return the expected error code.', '0b737e88-3a81-4f88-8534-f460bb1de60d', '2026-03-19 06:39:40.094902', '2026-03-19 06:39:40.094903');
DELETE FROM test_step WHERE script_id = 'dfa46b6c-5694-4164-8c04-6e4de3109c2e';
