INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('153969cc-349d-48ed-8bfa-7373a94b19ed', 'STEP 1', '1. Under the XDNS module, identify all the parameters with the read-only access type which are applicable for the device platform under test.
2. For all such parameters, perform a SET operation with a new value in line with the parameters''s datatype using WebPA protocol.
3. Check if the SET operation returns a FAILURE with the expected error code.
4. Return success if all read-only parameters fail with the expected return code. Else, return failure and publish the failed parameters list.', 'Setting the "read-only" TR-181 DML parameters under the XDNS module using WebPA protocol should return error code.', '057de6c5-6452-44ee-bb99-6a722178b156', '2026-03-19 06:39:37.860642', '2026-03-19 06:39:37.860644');
