INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2452de97-9188-4557-be1a-468654c42f96', 'STEP 2', 'Iterate through the Host Table and find any WiFi client entry', 'Device.Hosts.Host.{i}.Layer1Interface should contain a valid interface path', '46b01cb2-07c6-4a68-8fbd-a799f8731eec', '2026-04-01 07:00:02.988577', '2026-04-01 07:00:02.988578');
