INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('17b53933-a8ab-4cc8-86d5-1d8ca15c1995', 'STEP 1', '1. For all parameters under the Wan Manager module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Initiate a SET operation using WebPA protocol on all those parameters with the same value retrieved using the previous GET operation and with the parameter''s datatype.
3. The parameter will be write-access compliant if the SET operation does not fail with read-only error code.
4. Return success if all applicable parameters are write-access compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in Wan Manager module should not throw read-only error code when a SET operation is attempted on it using WebPA protocol.', '9b6452c2-050b-45f9-8e27-d5c7bbe3b062', '2026-03-19 06:39:38.167843', '2026-03-19 06:39:38.167844');
