INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2ce3f3df-dc77-4ecb-beb1-f6fefaff2faf', 'Vulkan Graphics Pipeline and Sphere Mesh Initialization', 'Initialize Vulkan instance, create Wayland surface, select physical device and graphics queue family, create logical device and swapchain. Generate sphere mesh geometry, setup vertex/index buffers.', 'Vulkan graphics pipeline must be created successfully, sphere mesh generated with appropriate vertex count and indices based on quality setting, geometry buffers allocated.', '7fd6e9a3-ad88-4173-a1f3-79e23f75d92d', '2026-03-27 12:16:59.346741', '2026-03-27 12:16:59.346741');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('36bb4961-6c30-4761-a2bb-9fc712290c65', 'Object Creation and Scene Setup', 'Create specified number of sphere objects (--objects parameter), initialize per-object properties (position, rotation speed, color), setup instance buffer for MVP matrices and colors, create render pass and framebuffers.', 'All sphere objects must be created with randomized properties, instance buffer allocated for per-object data, rendering pipeline ready for instanced drawing.', '7fd6e9a3-ad88-4173-a1f3-79e23f75d92d', '2026-03-27 12:16:59.348469', '2026-03-27 12:16:59.348469');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('49ca1a79-62f2-46ad-9de5-714c7bfceccd', 'CPU Work Simulation and Performance Monitoring', 'Execute main rendering loop for specified frame count, simulate CPU workload per object based on --cpu-work parameter (0=light, 1=medium, 2=heavy), calculate real-time FPS and CPU usage every second, update per-object transformations.', 'CPU workload simulation must execute as configured, FPS and CPU metrics calculated accurately, object animations updated smoothly with proper matrix calculations.', '7fd6e9a3-ad88-4173-a1f3-79e23f75d92d', '2026-03-27 12:16:59.349391', '2026-03-27 12:16:59.349392');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('82578ede-c9c0-47ea-9efd-f4481564e3fa', 'Instanced Rendering and CSV Data Export', 'Render all sphere objects in single draw call using instanced rendering, update instance buffer with per-object MVP matrices and colors, export performance data to CSV file including API, object count, quality, CPU work level, FPS and CPU usage.', 'll spheres must be rendered efficiently using Vulkan instanced drawing, CSV file updated with performance metrics in format: "Vulkan,resolution,objects,quality,cpuWork,fps,cpu_usage".', '7fd6e9a3-ad88-4173-a1f3-79e23f75d92d', '2026-03-27 12:16:59.350255', '2026-03-27 12:16:59.350256');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1cfc77a9-c146-4425-bfd6-9db0dd9c4518', 'Test Completion and Resource Cleanup', 'Complete rendering after specified frame count, calculate final average FPS and CPU usage statistics, display performance summary, properly destroy all Vulkan resources (buffers, pipelines, device, instance).', 'Test must complete after exact frame count reached, final performance statistics calculated correctly, all Vulkan objects and memory properly released without leaks.', '7fd6e9a3-ad88-4173-a1f3-79e23f75d92d', '2026-03-27 12:16:59.351898', '2026-03-27 12:16:59.351900');
DELETE FROM test_step WHERE script_id = '221896f6-1fc8-4d8d-a496-da9e16754a79';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1f1972d9-97aa-44ee-a911-19f739ba9cc7', 'STEP 1', '1. For all parameters under the TELEMETRY module which are applicable for the device platform under test, perform a GET operation.
2. Initiate a SET operation on all those parameters with the same value retrieved using the previous GET operation and with the parameter''s datatype.
3. The parameter will be write-access compliant if the SET operation does not fail with read-only error code.
4. Return success if all applicable parameters are write-access compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in TELEMETRY module should not throw error code when a SET operation is attempted on it.', '221896f6-1fc8-4d8d-a496-da9e16754a79', '2026-03-19 06:39:38.209240', '2026-03-19 06:39:38.209241');
DELETE FROM test_step WHERE script_id = '36042681-0c50-4eb4-9bb2-12ea8329cb1f';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1fb71499-c4c8-4f17-ad2d-7cd7b3880a11', 'STEP 1', '1. For all parameters under the MISC module which are applicable for the device platform under test, perform a GET operation.
2. Check if the datatype of the value retrieved from the GET operation is type-compliant with respect to the RDKB specification.
3. If the parameter value complies with the expected type, proceed to verify whether it belongs to the list of expected values defined in the RDKB specification or, if not provided by RDKB, aligns with the Broadband Forum standard.
4. Return success if all parameter values are type compliant and falls in the expected value list. Else, return failure and publish the failed parameters list.', 'All DML parameter values retrieved under MISC module should be type compliant and the value must be from expected values list.', '36042681-0c50-4eb4-9bb2-12ea8329cb1f', '2026-03-19 06:39:41.596098', '2026-03-19 06:39:41.596099');
DELETE FROM test_step WHERE script_id = 'c1867702-7892-41bb-8c51-b37970039ac1';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('20df53a3-afd7-4d4c-9381-2f1495d6c365', 'STEP 1', '1. Identify all table objects of type "dynamicTable" under the Test and Diagnostics module which are applicable for the device platform under test.
2. For all applicable Dynamic Tables, get the current number of rows.
3. For Dynamic Tables with row count greater than 0, perform a delete table row operation of the last table row instance using WebPA protocol.
4. Check if the delete table row operation fails with the expected error code for Dynamic Tables.
5. Return success if rows do not get deleted from the applicable Dynamic Tables. Else, return failure and publish the failed tables.', 'Deleting rows from dynamic table objects under TDM module using WebPA protocol should return the expected errorcode.', 'c1867702-7892-41bb-8c51-b37970039ac1', '2026-03-19 06:39:41.509380', '2026-03-19 06:39:41.509381');
DELETE FROM test_step WHERE script_id = '5d2b9035-8194-4edf-8398-ae3bc1912359';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('20f0450b-ab46-4fb1-8925-cedcceab4487', 'STEP 1', '1. Under the MOCA module, identify all the parameters with the read-only access type which are applicable for the device platform under test.
2. For all such parameters, perform a SET operation with a new value in line with the parameters''s datatype.
3. Check if the SET operation returns a FAILURE with the expected error code.
4. Return success if all read-only parameters fail with the expected return code. Else, return failure and publish the failed parameters list.', 'Setting the "read-only" TR-181 DML parameters under the MoCA module should return error code.', '5d2b9035-8194-4edf-8398-ae3bc1912359', '2026-03-19 06:39:38.992920', '2026-03-19 06:39:38.992921');
DELETE FROM test_step WHERE script_id = '64982ed1-62d5-4841-8149-04d99c4694b8';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('21280596-4d48-436b-86fe-48fe58ab6d88', 'STEP 1', '1. For all parameters under the VLANMANAGER module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Check if the datatype of the value retrieved from the GET operation is type-compliant with respect to the RDKB specification.
3. If the parameter value complies with the expected type, proceed to verify whether it belongs to the list of expected values defined in the RDKB specification or, if not provided by RDKB, aligns with the Broadband Forum standard.
4. Return success if all parameter values are type compliant and falls in the expected value list. Else, return failure and publish the failed parameters list.', 'All DML parameter values retrieved under VLANMANAGER module using WebPA protocol should be type compliant and the value must be from expected values list.', '64982ed1-62d5-4841-8149-04d99c4694b8', '2026-03-19 06:39:39.434091', '2026-03-19 06:39:39.434092');
DELETE FROM test_step WHERE script_id = '6c434694-d32b-47ad-a007-1cc1bdf83a47';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('216fce08-9726-4446-b5aa-f65e883dd94a', 'STEP 1', '1. For writable parameters, check if L2 SET use-case is defined.
2. For those parameters with L2 SET use-case defined, get the initial value. Return failure if get operation fails.
3. Then determine the value to be SET from the permissible value ranges of SET values.
4. For the SET value determined, get the initial values of defined dependencies if any. Return failure if any of the get operations fail.
5. Execute the SET operation of the parameters after all dependencies are SET successfully. If any of the SET operations fail, return failure.
6. Confirm with GET operation if all values are SET properly. Return failure if any SET value did not reflect in GET.
7. Now, revert the parameter to the initial value after identifying all revert dependencies and setting them. Return failure if any SET operations fail during revert or if SET does not reflect in GET.', 'All L2 SET operations should be successful and the corresponding use-cases under WANMANAGER module should be validated successfully.', '6c434694-d32b-47ad-a007-1cc1bdf83a47', '2026-03-19 06:39:41.534237', '2026-03-19 06:39:41.534238');
DELETE FROM test_step WHERE script_id = 'efbd6f98-1a19-449b-800a-62f5503865b2';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('21e3af2c-7c34-4163-9a07-8e9ad744f707', 'STEP 1', '1. For all parameters under the Notify Comp module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Initiate a SET operation on all those parameters with the same value retrieved using the previous GET operation but with an incorrect datatype using WebPA protocol.
3. The parameter will be write type compliant if the SET operations fail with the expected error code.
4. Return success if all applicable parameters are write type compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in Notify Comp module should throw the expected error code when a SET operation is attempted on it with an invalid parameter type using WebPA protocol.', 'efbd6f98-1a19-449b-800a-62f5503865b2', '2026-03-19 06:39:38.837884', '2026-03-19 06:39:38.837885');
DELETE FROM test_step WHERE script_id = '7ddfe701-f91e-41c1-8044-5131ad987d7f';
