INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2bc3676b-e0c5-4312-a578-eb9f9639ec89', 'STEP 1', '1. For all parameters under the Wan Manager module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Initiate a SET operation on all those parameters with the same value retrieved using the previous GET operation but with an incorrect datatype using WebPA protocol.
3. The parameter will be write type compliant if the SET operations fail with the expected error code.
4. Return success if all applicable parameters are write type compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in Wan Manager module should throw the expected error code when a SET operation is attempted on it with an invalid parameter type using WebPA protocol.', '28b09246-bee3-48d5-b86b-64f87468f85e', '2026-03-19 06:39:39.545160', '2026-03-19 06:39:39.545161');
