INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2bfcea58-c08a-4cee-8edc-f0b5e4f6b9d4', 'STEP 1', '1. Identify all table objects of type "dynWritableTable" under the LMLite module which are applicable for the device platform under test.
2. Perform an add table row operation and ensure that it returns success, if not, collect the failed table name.
3. After a successful add table operation, check if all expected parameters are found under that table instance using a getnames operation (GETN). If not collect the failed table name.
4. If the add table row operation is success, proceed to delete the same added table row instance.
5. Check if the delete table row operation is success, if not collect the failed table name.
6. Return success if add table row, getnames operation under the added table instance and delete table row operations are all success. Else, return failure and publish the failed tables.', 'Adding and deleting rows to/from dynamic writable tables should be success and the added table instance should have all the required parameters under it for LMLITE module.', 'f4edc60b-08dd-457e-b821-06be38381a10', '2026-03-19 06:39:41.101271', '2026-03-19 06:39:41.101272');
