INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('413cec3f-18c3-4eca-811b-569ca39e4f21', 'STEP 1', '1. Identify all table objects of type "dynamicTable" under the LMLite module which are applicable for the device platform under test.
