INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('41689367-250d-486d-a1cb-0c853193f879', 'STEP 1', '1. For all parameters under the WIFI module which are applicable for the device platform under test, perform a GET operation.
2. Initiate a SET operation on all those parameters with the same value retrieved using the previous GET operation but with an incorrect datatype.
3. The parameter will be write-type compliant if the SET operations fail with the expected error code.
4. Return success if all applicable parameters are write-type compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in WIFI module should throw the expected error code when a SET operation is attempted on it with an invalid parameter type.', 'beaf3718-038e-4168-a3f9-15b5f30f8e38', '2026-03-19 06:39:40.449223', '2026-03-19 06:39:40.449224');
