INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('52675873-1467-4386-906a-e437ffae2a2b', 'STEP 1', '1. Identify all table objects of type "staticTable" under the Wan Manager module which are applicable for the device platform under test.
