INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5d56ef82-3b87-406e-9f40-8ea83b9e6493', 'STEP 1', '1. For writable parameters, check if L2 SET use-case is defined.
2. For those parameters with L2 SET use-case defined, get the initial value. Return failure if get operation fails.
3. Then determine the value to be SET from the permissible value ranges of SET values.
4. For the SET value determined, get the initial values of defined dependencies if any. Return failure if any of the get operations fail.
5. Execute the SET operation of the parameters after all dependencies are SET successfully. If any of the SET operations fail, return failure.
6. Confirm with GET operation if all values are SET properly. Return failure if any SET value did not reflect in GET.
7. Now, revert the parameter to the initial value after identifying all revert dependencies and setting them. Return failure if any SET operations fail during revert or if SET does not reflect in GET.', 'All L2 SET operations should be successful and the corresponding use-cases under CM module should be validated successfully.', 'c0bd213d-8232-4870-ac63-cc6883adb77f', '2026-03-19 06:39:36.695985', '2026-03-19 06:39:36.695986');
