INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6f597856-57d8-47ee-a258-719c9efeaec7', 'STEP 1', '1. For all parameters under the MeshAgent module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
