INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('85011221-4ede-4393-adb1-bf19be9c3518', 'STEP 1', '1. Identify all table objects of type "writableTable" that are non-rigid under the WANMANAGER module which are applicable for the device platform under test.
2. Perform an add table row operation and ensure that it returns success, if not collect the failed table name.
3. After a successful add table operation, check if all expected parameters are found under that table instance using a getnames operation (GETN). If not collect the failed table name.
4. If the add table row operation is success, proceed to delete the same added table row instance.
5. Check if the delete table row operation is success, if not collect the failed table name.
6. Return success if add table row, getnames operation under the added table instance and delete table row operations are all success. Else, return failure and publish the failed tables.', 'Adding and deleting rows to/from non-rigid writable tables should be success and the added table instance should have all the required parameters under it for WANMANAGER module.', '76d894d7-39ce-4b0b-a3cf-d49127893bf1', '2026-03-19 06:39:38.611949', '2026-03-19 06:39:38.611951');
DELETE FROM test_step WHERE script_id = '91dcb205-de9f-404b-91b4-49b57f73819b';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8523a32c-602c-453a-9686-c1e04c2915fe', 'STEP 1', '1. Identify all table objects of type "staticTable" under the MTA module which are applicable for the device platform under test.
2. For all applicable Static Tables, get the current number of rows.
3. For Static Tables with row count greater than 0, perform a delete table row operation of the last table row instance.
4. Check if the delete table row operation fails with the expected error code for Static Tables.
5. Return success if rows do not get deleted from the applicable Static Tables. Else, return failure and publish the failed tables.', 'Deleting rows from static table objects under MTA module should return the expected errorcode.', '91dcb205-de9f-404b-91b4-49b57f73819b', '2026-03-19 06:39:40.489082', '2026-03-19 06:39:40.489083');
