INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9b7a2169-7ebc-4d93-a417-6b05780da696', 'STEP 1', '1. Under the Telemetry module, identify all the parameters with the read-only access type which are applicable for the device platform under test.
2. For all such parameters, perform a SET operation with a new value in line with the parameters''s datatype using WebPA protocol.
3. Check if the SET operation returns a FAILURE with the expected error code.
4. Return success if all read-only parameters fail with the expected return code. Else, return failure and publish the failed parameters list.', 'Setting the "read-only" TR-181 DML parameters under the Telemetry module using WebPA protocol should return error code.', '3bd57c46-0eff-4472-9cb6-ea8f9bfa18f8', '2026-03-19 06:39:41.044503', '2026-03-19 06:39:41.044505');
