INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9c3a1fe3-c0e0-4f21-851b-04bf24d13e0e', 'STEP 1', '1. For all parameters under the Test and Diagnostic module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Initiate a SET operation using WebPA protocol on all those parameters with the same value retrieved using the previous GET operation and with the parameter''s datatype.
3. The parameter will be write-access compliant if the SET operation does not fail with read-only error code.
4. Return success if all applicable parameters are write-access compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in Test and Diagnostic module should not throw read-only error code when a SET operation is attempted on it using WebPA protocol.', 'de3ac3e8-13c4-4125-8149-8f28d3c96988', '2026-03-19 06:39:37.164754', '2026-03-19 06:39:37.164755');
