INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9e462372-eab4-40da-b953-bbc7acca8e88', 'STEP 1', '1. Under the MISC module, identify all the parameters with the read-only access type which are applicable for the device platform under test.
