INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b9e4aa6f-6503-4ba8-a14b-35806cbcba31', 'STEP 1', '1. For all parameters under the LMLite module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
