INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bb17c501-e6ae-40d0-9b52-18f1754fa95d', 'STEP 1', '1. Identify all table objects of type "dynamicTable" under the EthAgent module which are applicable for the device platform under test.
2. For all applicable Dynamic Tables, get the current number of rows.
3. For Dynamic Tables with row count greater than 0, perform a delete table row operation of the last table row instance.
4. Check if the delete table row operation fails with the expected error code for Dynamic Tables.
5. Return success if rows do not get deleted from the applicable Dynamic Tables. Else, return failure and publish the failed tables.', 'Adding rows to dynamic table objects under ETHAGENT module should return the expected errorcode.', '60fcc3ad-94b1-4832-b425-385362dace09', '2026-03-19 06:39:38.817545', '2026-03-19 06:39:38.817546');
