INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bb1e937e-8425-4443-933a-fa742c4dbae6', 'STEP 1', '1. For all parameters under the IDM module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Check if the datatype of the value retrieved from the GET operation is type-compliant with respect to the RDKB specification.
3. If the parameter value complies with the expected type, proceed to verify whether it belongs to the list of expected values defined in the RDKB specification or, if not provided by RDKB, aligns with the Broadband Forum standard.
4. Return success if all parameter values are type compliant and falls in the expected value list. Else, return failure and publish the failed parameters list.', 'All DML parameter values retrieved under IDM module using WebPA protocol should be type compliant and the value must be from expected values list.', '47852a7f-e94f-43e0-857d-3f8e90ad976c', '2026-03-19 06:39:36.232772', '2026-03-19 06:39:36.232773');
