INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bd4408e4-c0d3-4dab-bb52-f68631c23f1b', 'STEP 1', '1. For all parameters under the Component Registry module which are applicable for the device platform under test, perform a GET operation using WebPA protocol.
2. Initiate a SET operation on all those parameters with the same value retrieved using the previous GET operation but with an incorrect datatype using WebPA protocol.
3. The parameter will be write type compliant if the SET operations fail with the expected error code.
4. Return success if all applicable parameters are write type compliant. Else, return failure and publish the failed parameters list.', 'Writable parameters in Component Registry module should throw the expected error code when a SET operation is attempted on it with an invalid parameter type using WebPA protocol.', '19f6135d-13b1-4f47-ab56-73350c5177ea', '2026-03-19 06:39:41.133074', '2026-03-19 06:39:41.133075');
